CREATE TABLE IF NOT EXISTS reading_conversion (
    conversion_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    equipment_id VARCHAR(64) NOT NULL,
    reading_id VARCHAR(64) NOT NULL,
    revision_no INT NOT NULL,
    submitted_unit VARCHAR(8) NOT NULL,
    submitted_value DECIMAL(19,6) NOT NULL,
    converted_value DECIMAL(19,6) NOT NULL,
    converted_minutes BIGINT NOT NULL,
    equalized_by_rounding BOOLEAN NOT NULL,
    request_id VARCHAR(128) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_conversion_equipment ON reading_conversion (equipment_id, conversion_id);
COMMENT ON TABLE reading_conversion IS '读数单位换算留痕：跨单位提交时记录原始值与换算结果，只读可追溯';
COMMENT ON COLUMN reading_conversion.conversion_id IS '换算记录自增主键';
COMMENT ON COLUMN reading_conversion.equipment_id IS '所属设备标识';
COMMENT ON COLUMN reading_conversion.reading_id IS '换算后写入的读数标识';
COMMENT ON COLUMN reading_conversion.revision_no IS '该换算产生的读数修订号';
COMMENT ON COLUMN reading_conversion.submitted_unit IS '提交时附带的单位标签（与设备登记单位不同）';
COMMENT ON COLUMN reading_conversion.submitted_value IS '提交的原始值（按提交单位）';
COMMENT ON COLUMN reading_conversion.converted_value IS '换算后存储值（按设备登记单位）';
COMMENT ON COLUMN reading_conversion.converted_minutes IS '换算后分钟数（判定口径，四舍五入到整数分钟）';
COMMENT ON COLUMN reading_conversion.equalized_by_rounding IS '换算误差导致与相邻读数相等（视为非递减放行）时为 TRUE';
COMMENT ON COLUMN reading_conversion.request_id IS '产生该换算的请求 requestId';
COMMENT ON COLUMN reading_conversion.created_at IS '换算记录时刻（UTC）';

