import jakarta.validation.constraints.PositiveOrZero;

/**
 * 登记设备请求。计量单位（MINUTES/HOURS）与保养周期登记后不可修改。
 * 单位缺省为 MINUTES；MINUTES 设备使用 maintenancePeriodMinutes（正整数分钟），
 * HOURS 设备使用 maintenancePeriod（十进制小时，最多 2 位小数）。
 *
 * @param requestId                 全局唯一请求标识（幂等键）
 * @param equipmentId               设备唯一标识
 * @param maintenancePeriodMinutes  保养周期（分钟），正整数；unit 缺省或 MINUTES 时必填
 * @param unit                      计量单位（MINUTES/HOURS），缺省 MINUTES，登记后不可更改
 * @param maintenancePeriod         保养周期（按声明单位，十进制最多 2 位小数）；unit 为 HOURS 时必填
 */
public record RegisterEquipmentRequest(
        @NotBlank String requestId,
        @NotBlank String equipmentId,
        @Positive Long maintenancePeriodMinutes,
        String unit,
        @PositiveOrZero BigDecimal maintenancePeriod) {
}

package com.example.starter.maintenance.api.dto;

import java.math.BigDecimal;
import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 新增工时读数请求。允许补录历史读数，但按采样时刻排序后累计分钟须单调不减。
 * 可附带单位标签：与设备登记单位一致时按登记单位解释；不同时必须提供 cumulativeValue，
 * 由服务端按 BigDecimal 规则换算为设备单位后参与单调性比较，并记录换算留痕。
 *
 * @param requestId          全局唯一请求标识（幂等键）
 * @param expectedVersion    设备期望版本号，与当前版本不一致时返回 409
 * @param readingId          读数标识，设备内唯一
 * @param sampledAt          UTC 采样时刻；同设备同一时刻仅允许一条读数
 * @param cumulativeMinutes  累计工时（分钟），非负整数；设备单位为 MINUTES 且未附带单位标签时必填
 * @param unit               可选单位标签（MINUTES/HOURS），缺省按设备登记单位解释
 * @param cumulativeValue    累计工时（按 unit 指定的单位，十进制最多 2 位小数）
 */
public record AddReadingRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotBlank String readingId,
        @NotNull Instant sampledAt,
        @PositiveOrZero Long cumulativeMinutes,
        String unit,
        @PositiveOrZero BigDecimal cumulativeValue) {
}

package com.example.starter.maintenance.api.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 修订读数请求：只改变累计工时，不改采样时刻；作为历史保养锚点的读数不可修订（409）。
 * 单位换算规则与新增读数一致：附带单位标签与设备登记单位不同时换算并留痕。
 *
 * @param requestId          全局唯一请求标识（幂等键）
 * @param expectedVersion    设备期望版本号，与当前版本不一致时返回 409
 * @param cumulativeMinutes  修订后的累计工时（分钟），非负整数；设备单位为 MINUTES 且未附带单位标签时必填
 * @param unit               可选单位标签（MINUTES/HOURS），缺省按设备登记单位解释
 * @param cumulativeValue    修订后的累计工时（按 unit 指定的单位，十进制最多 2 位小数）
 */
public record ReviseReadingRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @PositiveOrZero Long cumulativeMinutes,
        String unit,
        @PositiveOrZero BigDecimal cumulativeValue) {
}

