    void idempotency_crossUnitReplayAndMismatch() throws Exception {
        postJson("/api/equipment", """
                {"requestId":"reg-i1","equipmentId":"eq-i1","maintenancePeriodMinutes":1000}
                """);

        MvcResult first = postJson("/api/equipment/eq-i1/readings", """
